CREATE OR REPLACE FUNCTION public.fusion_review_breaker_usage(a uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
